import urllib.request,concurrent.futures
urls=['https://raw.githubusercontent.com/AssemblyAI/assemblyai-python-sdk/master/assemblyai/types.py','https://api.assemblyai.com/v2/openapi.json','https://www.assemblyai.com/docs/api-reference/transcripts/submit.mdx','https://assemblyai.com/docs/pre-recorded-audio/select-the-language-to-transcribe']
def get(u):
 try:
  r=urllib.request.urlopen(u,timeout=15);d=r.read().decode();p='/tmp/'+('assemblyai-types.py' if 'types.py' in u else str(urls.index(u))+'.html');open(p,'w').write(d);return u,r.status,len(d),p
 except Exception as e:return u,str(e)
for r in concurrent.futures.ThreadPoolExecutor().map(get,urls):print(r)
PY"

